CREATE TABLE public.guard_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,session_key text NOT NULL,note_date date NOT NULL,period text NOT NULL,locked_at timestamptz,lock_reason text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,session_key));
GRANT SELECT ON public.guard_sessions TO authenticated; GRANT ALL ON public.guard_sessions TO service_role; ALTER TABLE public.guard_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY guard_sessions_own ON public.guard_sessions FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.guard_trades(id uuid PRIMARY KEY,session_id uuid NOT NULL REFERENCES public.guard_sessions(id),user_id uuid NOT NULL,instrument text NOT NULL,account text NOT NULL DEFAULT 'Default',outcome text NOT NULL CHECK(outcome IN ('win','loss','breakeven')),pnl numeric(18,2) NOT NULL,note text NOT NULL DEFAULT '',direction text NOT NULL DEFAULT '',occurred_at timestamptz NOT NULL DEFAULT now(),undone_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.guard_trades TO authenticated; GRANT ALL ON public.guard_trades TO service_role; ALTER TABLE public.guard_trades ENABLE ROW LEVEL SECURITY; CREATE POLICY guard_trades_own ON public.guard_trades FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE INDEX guard_trades_session ON public.guard_trades(session_id,created_at);
CREATE FUNCTION public.guard_period(p_now timestamptz) RETURNS TABLE(session_key text,note_date date,period text,window_open boolean) LANGUAGE sql STABLE SET search_path=public AS $$ WITH p AS(SELECT p_now AT TIME ZONE 'America/Los_Angeles' AS t), s AS(SELECT (CASE WHEN t::time<'06:15' THEN t::date-1 ELSE t::date END) AS d,CASE WHEN t::time>='16:50' OR t::time<'06:15' THEN 'gold' ELSE 'ny-open' END AS k,((t::time>='06:20' AND t::time<'07:30') OR (t::time>='17:00' AND t::time<'19:15')) AS w FROM p) SELECT d::text||CASE WHEN k='gold' THEN '-pm' ELSE '-am' END,d,k,w FROM s $$;
REVOKE ALL ON FUNCTION public.guard_period(timestamptz) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.guard_period(timestamptz) TO authenticated,service_role;
CREATE FUNCTION public.commit_guard_trade(p_user uuid,p_id uuid,p_instrument text,p_account text,p_outcome text,p_pnl numeric,p_note text,p_direction text,p_session text) RETURNS public.guard_trades LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_period record; v_session public.guard_sessions; v_trade public.guard_trades; v_body jsonb; v_trades jsonb; v_count integer; v_win boolean; BEGIN
 SELECT * INTO v_period FROM public.guard_period(now());
 PERFORM pg_advisory_xact_lock(hashtextextended(p_user::text||':guard',0));
 SELECT * INTO v_trade FROM public.guard_trades WHERE id=p_id AND user_id=p_user;
 IF FOUND THEN IF v_trade.instrument IS DISTINCT FROM p_instrument OR v_trade.account IS DISTINCT FROM p_account OR v_trade.outcome IS DISTINCT FROM p_outcome OR v_trade.pnl IS DISTINCT FROM p_pnl OR v_trade.note IS DISTINCT FROM p_note OR v_trade.direction IS DISTINCT FROM p_direction THEN RAISE EXCEPTION 'Submission already used'; END IF; RETURN v_trade; END IF;
 IF p_session IS DISTINCT FROM v_period.session_key THEN RAISE EXCEPTION 'Session changed; reload before logging'; END IF;
 IF NOT v_period.window_open THEN RAISE EXCEPTION 'Outside trading window'; END IF;
 IF p_id IS NULL OR p_outcome NOT IN ('win','loss','breakeven') OR p_pnl IS NULL OR p_pnl::text IN ('NaN','Infinity','-Infinity') OR abs(p_pnl)>999999999999 OR (p_outcome='win' AND p_pnl<=0) OR (p_outcome='loss' AND p_pnl>=0) OR (p_outcome='breakeven' AND p_pnl>0) OR p_instrument NOT IN ('NQ','MNQ','YM','MYM','GC','MGC') OR char_length(p_account)>100 OR char_length(p_note)>2000 OR p_direction NOT IN ('','long','short') THEN RAISE EXCEPTION 'Invalid trade'; END IF;
 INSERT INTO public.guard_sessions(user_id,session_key,note_date,period) VALUES(p_user,v_period.session_key,v_period.note_date,v_period.period) ON CONFLICT(user_id,session_key) DO NOTHING;
 SELECT * INTO v_session FROM public.guard_sessions WHERE user_id=p_user AND session_key=v_period.session_key FOR UPDATE;
 IF v_session.locked_at IS NOT NULL THEN RAISE EXCEPTION 'Session locked'; END IF;
 INSERT INTO public.guard_trades(id,session_id,user_id,instrument,account,outcome,pnl,note,direction) VALUES(p_id,v_session.id,p_user,p_instrument,p_account,p_outcome,p_pnl,p_note,p_direction) RETURNING * INTO v_trade;
 SELECT count(*),COALESCE(bool_or(outcome='win'),false) INTO v_count,v_win FROM public.guard_trades WHERE session_id=v_session.id AND undone_at IS NULL;
 UPDATE public.guard_sessions SET locked_at=CASE WHEN v_win OR v_count>=3 THEN now() END,lock_reason=CASE WHEN v_win THEN 'one-win' WHEN v_count>=3 THEN 'three-trade-limit' END,updated_at=now() WHERE id=v_session.id;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',id::text,'instrument',instrument,'direction',direction,'result',outcome,'pnl',pnl::text,'note',note,'account',account,'occurredAt',occurred_at) ORDER BY created_at),'[]'::jsonb) INTO v_trades FROM public.guard_trades WHERE session_id=v_session.id AND undone_at IS NULL;
 SELECT body::jsonb INTO v_body FROM public.member_notes WHERE user_id=p_user AND note_date=v_period.note_date AND session=v_period.period||'#guard'; v_body:=COALESCE(v_body,'{}'::jsonb)||jsonb_build_object('session',v_period.period,'trades',v_trades);
 PERFORM set_config('shlm.guard_write','yes',true);
 INSERT INTO public.member_notes(user_id,note_date,session,body) VALUES(p_user,v_period.note_date,v_period.period||'#guard',v_body::text) ON CONFLICT(user_id,note_date,session) DO UPDATE SET body=EXCLUDED.body,updated_at=now();
 RETURN v_trade; END $$;
REVOKE ALL ON FUNCTION public.commit_guard_trade(uuid,uuid,text,text,text,numeric,text,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.commit_guard_trade(uuid,uuid,text,text,text,numeric,text,text,text) TO service_role;
CREATE FUNCTION public.undo_guard_trade(p_user uuid,p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_trade public.guard_trades; v_session public.guard_sessions; v_last uuid; v_count integer; v_win boolean; v_trades jsonb; BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended(p_user::text||':guard',0));
 SELECT * INTO v_trade FROM public.guard_trades WHERE id=p_id AND user_id=p_user FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Trade not found'; END IF; IF v_trade.undone_at IS NOT NULL THEN RETURN; END IF;
 SELECT * INTO v_session FROM public.guard_sessions WHERE id=v_trade.session_id FOR UPDATE;
 SELECT id INTO v_last FROM public.guard_trades WHERE session_id=v_session.id ORDER BY created_at DESC LIMIT 1;
 IF v_last<>p_id OR now()-v_trade.created_at>=interval '15 seconds' THEN RAISE EXCEPTION 'Undo window ended'; END IF;
 UPDATE public.guard_trades SET undone_at=now() WHERE id=p_id;
 SELECT count(*),COALESCE(bool_or(outcome='win'),false) INTO v_count,v_win FROM public.guard_trades WHERE session_id=v_session.id AND undone_at IS NULL;
 UPDATE public.guard_sessions SET locked_at=CASE WHEN v_win OR v_count>=3 THEN locked_at END,lock_reason=CASE WHEN v_win THEN 'one-win' WHEN v_count>=3 THEN 'three-trade-limit' END,updated_at=now() WHERE id=v_session.id;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',id::text,'instrument',instrument,'direction',direction,'result',outcome,'pnl',pnl::text,'note',note,'account',account,'occurredAt',occurred_at) ORDER BY created_at),'[]'::jsonb) INTO v_trades FROM public.guard_trades WHERE session_id=v_session.id AND undone_at IS NULL;
 PERFORM set_config('shlm.guard_write','yes',true); UPDATE public.member_notes SET body=(body::jsonb||jsonb_build_object('trades',v_trades))::text,updated_at=now() WHERE user_id=p_user AND note_date=v_session.note_date AND session=v_session.period||'#guard'; END $$;
REVOKE ALL ON FUNCTION public.undo_guard_trade(uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.undo_guard_trade(uuid,uuid) TO service_role;
CREATE FUNCTION public.protect_guard_journal() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
 IF current_setting('shlm.guard_write',true)='yes' AND current_user IN ('postgres','service_role','supabase_admin') THEN IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF;
 IF TG_OP='DELETE' AND OLD.session LIKE '%#guard' THEN RAISE EXCEPTION 'Guard session history cannot be deleted'; END IF;
 IF TG_OP='INSERT' AND NEW.session LIKE '%#guard' THEN RAISE EXCEPTION 'Use shared trade logging'; END IF;
 IF TG_OP='UPDATE' AND (OLD.session LIKE '%#guard' OR NEW.session LIKE '%#guard') AND (NEW.session IS DISTINCT FROM OLD.session OR NEW.note_date IS DISTINCT FROM OLD.note_date OR NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.body::jsonb->'trades' IS DISTINCT FROM OLD.body::jsonb->'trades') THEN RAISE EXCEPTION 'Guard trades cannot be changed through Journal'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $$;
CREATE TRIGGER guard_journal_protect BEFORE INSERT OR UPDATE OR DELETE ON public.member_notes FOR EACH ROW EXECUTE FUNCTION public.protect_guard_journal();
CREATE TRIGGER guard_sessions_updated BEFORE UPDATE ON public.guard_sessions FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
ALTER PUBLICATION supabase_realtime ADD TABLE public.guard_sessions,public.guard_trades;